"use client";

export function bgShade(hex, t) {
  const h = (hex || "#000000").replace("#", "");
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  const tgt = t >= 0 ? 255 : 0;
  const a = Math.abs(t);
  const m = (c) => Math.round(c + (tgt - c) * a);
  return `rgb(${m(r)},${m(g)},${m(b)})`;
}

// rgba variant so layers can blend softly instead of stacking as opaque fills.
function bgShadeA(hex, t, alpha) {
  const h = (hex || "#000000").replace("#", "");
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  const tgt = t >= 0 ? 255 : 0;
  const a = Math.abs(t);
  const m = (c) => Math.round(c + (tgt - c) * a);
  return `rgba(${m(r)},${m(g)},${m(b)},${alpha})`;
}

const fill = {
  position: "absolute",
  inset: 0,
  width: "100%",
  height: "100%",
  zIndex: 0,
  pointerEvents: "none",
};

// A soft inner vignette layer reused across designs to add depth and keep the
// card content readable (edges darken slightly, center stays luminous).
function vignette(bg, strength = 0.22) {
  return {
    ...fill,
    background: `radial-gradient(120% 90% at 50% 38%, transparent 45%, ${bgShadeA(
      bg,
      -0.55,
      strength,
    )} 100%)`,
  };
}

