export function CssDesign({ design, bg, accent, lighting }) {
  const aL = bgShade(accent, 0.3);
  const aD = bgShade(accent, -0.2);
  const bL = bgShade(bg, 0.28);
  const bD = bgShade(bg, -0.18);
  const bLL = bgShade(bg, 0.42);
  const bDD = bgShade(bg, -0.34);
  // Lighting control (per-pet, per-design). Values are MULTIPLIERS on each
  // design's built-in defaults, so 1 = original look, 0 = off, >1 = stronger.
  //   x, y       — absolute light-bloom origin (%, gradient design uses these)
  //   intensity  — bloom-strength multiplier (1 = design default)
  //   vignette   — edge-darkening multiplier (1 = design default)
  //   depth      — gradient strength: 1 = full gradient, 0 = solid bg
  const lx = lighting?.x ?? 24;
  const ly = lighting?.y ?? 18;
  const lIntMul = lighting?.intensity ?? 1;
  const lVigMul = lighting?.vignette ?? 1;
  const lDepth = lighting?.depth ?? 1;
  // Per-design vignette: multiply the design's own default by the user's mult.
  const vig = (designDefault) => vignette(bg, designDefault * lVigMul);
  // Parse a color that may be a hex string ("#1A2D44") OR an rgb() string
  // (which bgShade returns) into [r,g,b]. bgShade only accepts hex, so calling
  // it on an already-rgb() value (like bL/bD) produced NaN — that bug made the
  // depth/solid control fail. This parses both forms safely.
  const toRGB = (c) => {
    if (typeof c === "string" && c.trim().startsWith("rgb")) {
      const n = c.match(/\d+/g);
      return n ? n.slice(0, 3).map(Number) : [0, 0, 0];
    }
    const h = (c || "#000000").replace("#", "");
    return [
      parseInt(h.slice(0, 2), 16),
      parseInt(h.slice(2, 4), 16),
      parseInt(h.slice(4, 6), 16),
    ];
  };
  const mixHex = (colorA, colorB, t) => {
    const pa = toRGB(colorA);
    const pb = toRGB(colorB);
    const m = (i) => Math.round(pa[i] + (pb[i] - pa[i]) * t);
    return `rgb(${m(0)},${m(1)},${m(2)})`;
  };
  // Each gradient stop pulled toward bg by (1 - depth): depth 0 => solid bg.
  const dStop = (hex) => mixHex(hex, bg, 1 - lDepth);

  // Universal light bloom — a soft brightening at the chosen light position that
  // sits ON TOP of every design, so the Light Position control visibly affects
  // ALL backgrounds (not just a few). Strength follows the Brightness slider;
  // at intensity 0 it disappears.
  const lightBloom = (
    <div
      key="hb-light-bloom"
      style={{
        ...fill,
        background: `radial-gradient(60% 55% at ${lx}% ${ly}%, ${bgShadeA(
          bg,
          0.5,
          0.4 * lIntMul,
        )} 0%, transparent 60%)`,
        mixBlendMode: "screen",
        pointerEvents: "none",
      }}
    />
  );

  // Render the chosen design, then overlay the universal light bloom.
  const content = (() => {
    switch (design) {
      // Solid: a clean, near-flat background — base color + gentle vignette. The
      // flat counterpart to "Blend".
      case "solid":
        return (
          <div style={fill}>
            <div style={{ ...fill, background: dStop(bg) }} />
            <div style={vig(0.16)} />
          </div>
        );
      // Blend (formerly "gradient"): rich diagonal blend + light bloom + vignette.
      case "blend":
      case "gradient":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `linear-gradient(155deg, ${dStop(bLL)} 0%, ${dStop(
                  bL,
                )} 30%, ${dStop(accent)} 78%, ${dStop(aD)} 100%)`,
              }}
            />
            <div
              style={{
                ...fill,
                background: `radial-gradient(90% 70% at ${lx}% ${ly}%, ${bgShadeA(
                  bg,
                  0.55,
                  0.55 * lIntMul,
                )} 0%, transparent 55%)`,
                mixBlendMode: "screen",
              }}
            />
            <div style={vig(0.25)} />
          </div>
        );

      // Mesh gradient: several soft colour blooms melting together + vignette.
      case "mesh-grad":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `radial-gradient(at 16% 20%, ${accent} 0px, transparent 46%), radial-gradient(at 84% 26%, ${bLL} 0px, transparent 44%), radial-gradient(at 50% 86%, ${aL} 0px, transparent 50%), radial-gradient(at 88% 78%, ${aD} 0px, transparent 42%), radial-gradient(at 12% 80%, ${bL} 0px, transparent 46%), ${bg}`,
              }}
            />
            <div style={vig(0.2)} />
          </div>
        );

      // Aurora: stacked, blurred ribbons of light over a deep base.
      case "aurora-wash":
        return (
          <div style={{ ...fill, background: dStop(bD) }}>
            <div
              style={{
                ...fill,
                background: `radial-gradient(140% 60% at 20% 30%, ${bgShadeA(
                  accent,
                  0.3,
                  0.7,
                )} 0%, transparent 50%), radial-gradient(120% 55% at 78% 42%, ${bgShadeA(
                  accent,
                  -0.1,
                  0.6,
                )} 0%, transparent 48%), radial-gradient(130% 60% at 50% 78%, ${bgShadeA(
                  bg,
                  0.4,
                  0.6,
                )} 0%, transparent 52%)`,
                filter: "blur(6px)",
              }}
            />
            <div style={vig(0.28)} />
          </div>
        );

      // Spotlight: a luminous focal glow with smooth falloff + dark surround.
      case "spotlight":
        return (
          <div style={{ ...fill, background: bDD }}>
            <div
              style={{
                ...fill,
                background: `radial-gradient(circle at 50% 20%, ${bgShadeA(
                  accent,
                  0.35,
                  0.95,
                )} 0%, ${bgShadeA(accent, 0, 0.5)} 14%, transparent 46%)`,
              }}
            />
            <div
              style={{
                ...fill,
                background: `radial-gradient(circle at 50% 20%, ${bgShadeA(
                  bg,
                  0.5,
                  0.5,
                )} 0%, transparent 60%)`,
                mixBlendMode: "screen",
              }}
            />
            <div style={vig(0.3)} />
          </div>
        );

      // Grain: smooth gradient base with fine fractal-noise texture on top.
      case "grain":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `linear-gradient(135deg, ${dStop(bLL)} 0%, ${dStop(bL)} 40%, ${dStop(bg)} 70%, ${dStop(aD)} 100%)`,
              }}
            />
            <div
              style={{
                ...fill,
                background: `radial-gradient(80% 60% at 30% 25%, ${bgShadeA(
                  accent,
                  0.2,
                  0.4,
                )} 0%, transparent 55%)`,
                mixBlendMode: "screen",
              }}
            />
            <svg
              style={{ ...fill, opacity: 0.42, mixBlendMode: "overlay" }}
              xmlns="http://www.w3.org/2000/svg"
            >
              <filter id="grainNoise">
                <feTurbulence
                  type="fractalNoise"
                  baseFrequency="0.7"
                  numOctaves="4"
                  stitchTiles="stitch"
                />
                <feColorMatrix type="saturate" values="0" />
                <feComponentTransfer>
                  <feFuncA type="linear" slope="1.3" intercept="-0.2" />
                </feComponentTransfer>
              </filter>
              <rect width="100%" height="100%" filter="url(#grainNoise)" />
            </svg>
            <div style={vig(0.18)} />
          </div>
        );

      // Dots: dual-layer dot field (soft large + crisp small) over a gradient,
      // with a radial fade so it reads as premium texture, not flat polka dots.
      case "dots":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `linear-gradient(160deg, ${dStop(bL)} 0%, ${dStop(
                  bg,
                )} 60%, ${dStop(bD)} 100%)`,
              }}
            />
            <div
              style={{
                ...fill,
                backgroundImage: `radial-gradient(${bgShadeA(
                  accent,
                  0.2,
                  0.5,
                )} 3px, transparent 3.5px)`,
                backgroundSize: "46px 46px",
                backgroundPosition: "0 0",
              }}
            />
            <div
              style={{
                ...fill,
                backgroundImage: `radial-gradient(${bgShadeA(
                  accent,
                  -0.1,
                  0.85,
                )} 1.5px, transparent 2px)`,
                backgroundSize: "23px 23px",
                backgroundPosition: "11px 11px",
              }}
            />
            <div
              style={{
                ...fill,
                background: `radial-gradient(110% 80% at ${lx}% ${ly}%, transparent 30%, ${bgShadeA(
                  bg,
                  -0.3,
                  0.55 * lIntMul,
                )} 100%)`,
              }}
            />
            <div style={vig(0.2)} />
          </div>
        );

      // Stripes: thin, soft diagonal lines with a light sweep — delicate, not
      // barbershop.
      case "stripes":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `linear-gradient(125deg, ${dStop(bL)} 0%, ${dStop(bg)} 100%)`,
              }}
            />
            <div
              style={{
                ...fill,
                backgroundImage: `repeating-linear-gradient(48deg, ${bgShadeA(
                  accent,
                  0.15,
                  0.28,
                )} 0, ${bgShadeA(accent, 0.15, 0.28)} 2px, transparent 2px, transparent 22px)`,
              }}
            />
            <div
              style={{
                ...fill,
                background: `linear-gradient(48deg, transparent 0%, ${bgShadeA(
                  bg,
                  0.5,
                  0.3,
                )} 48%, transparent 70%)`,
                mixBlendMode: "screen",
              }}
            />
            <div style={vig(0.2)} />
          </div>
        );

      // Weave: thin lines crossing in two directions form a subtle plaid/diamond
      // texture, with a radial fade so it reads as soft fabric, not a grid.
      case "weave":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `linear-gradient(160deg, ${bL} 0%, ${bg} 60%, ${bD} 100%)`,
              }}
            />
            <div
              style={{
                ...fill,
                backgroundImage: `repeating-linear-gradient(48deg, ${bgShadeA(
                  accent,
                  0.15,
                  0.22,
                )} 0, ${bgShadeA(accent, 0.15, 0.22)} 1.5px, transparent 1.5px, transparent 26px)`,
              }}
            />
            <div
              style={{
                ...fill,
                backgroundImage: `repeating-linear-gradient(-48deg, ${bgShadeA(
                  bg,
                  0.5,
                  0.18,
                )} 0, ${bgShadeA(bg, 0.5, 0.18)} 1.5px, transparent 1.5px, transparent 26px)`,
              }}
            />
            <div
              style={{
                ...fill,
                background: `radial-gradient(110% 80% at ${lx}% ${ly}%, transparent 35%, ${bgShadeA(
                  bg,
                  -0.3,
                  0.5 * lIntMul,
                )} 100%)`,
              }}
            />
            <div style={vig(0.2)} />
          </div>
        );

      // Concentric rings: many thin, tightly-spaced rings radiating from a soft
      // focal bloom.
      case "concentric":
        return (
          <div style={{ ...fill, background: dStop(bD) }}>
            <svg
              viewBox="0 0 100 100"
              preserveAspectRatio="xMidYMid slice"
              style={fill}
              xmlns="http://www.w3.org/2000/svg"
              aria-hidden="true"
            >
              <defs>
                <radialGradient id="ringGlow" cx="50%" cy="44%" r="62%">
                  <stop offset="0%" stopColor={bgShadeA(accent, 0.4, 0.5)} />
                  <stop offset="42%" stopColor={bgShadeA(accent, 0, 0.13)} />
                  <stop offset="100%" stopColor="transparent" />
                </radialGradient>
              </defs>
              <rect width="100" height="100" fill="url(#ringGlow)" />
              {Array.from({ length: 44 }, (_, i) => 1.2 + i * 1.9).map(
                (r, i) => (
                  <circle
                    key={i}
                    cx="50"
                    cy="44"
                    r={r}
                    fill="none"
                    stroke={accent}
                    strokeWidth="0.1"
                    opacity={Math.max(0.05, 0.48 - i * 0.0075)}
                  />
                ),
              )}
            </svg>
            <div style={vig(0.26)} />
          </div>
        );

      // Maze: dense, fine, interconnected grid maze with layered depth — reads
      // zoomed-out and intricate while blending so foreground stays readable.
      case "maze":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `linear-gradient(160deg, ${dStop(bL)} 0%, ${dStop(bg)} 55%, ${dStop(bD)} 100%)`,
              }}
            />
            <div
              style={{
                ...fill,
                background: `radial-gradient(115% 90% at 50% 40%, ${bgShadeA(
                  accent,
                  0.12,
                  0.16,
                )} 0%, transparent 65%)`,
              }}
            />
            <svg
              viewBox="0 0 768 768"
              preserveAspectRatio="xMidYMid slice"
              style={fill}
              xmlns="http://www.w3.org/2000/svg"
              aria-hidden="true"
            >
              <g fill="none" strokeLinecap="round" strokeLinejoin="round">
                <path
                  d={MAZE_PATH}
                  stroke={bgShadeA(bg, -0.45, 0.4)}
                  strokeWidth="1.6"
                  transform="translate(0.9,1.1)"
                />
                <path
                  d={MAZE_PATH}
                  stroke={bgShadeA(accent, 0.1, 0.42)}
                  strokeWidth="1.3"
                />
                <path
                  d={MAZE_PATH}
                  stroke={bgShadeA(accent, 0.6, 0.5)}
                  strokeWidth="0.5"
                />
              </g>
            </svg>
            <div style={vig(0.22)} />
          </div>
        );

      // Cosmos: a dusty dot field at many sizes/depths over a night-sky
      // gradient — atmospheric, varied, soft.
      case "cosmos":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `radial-gradient(135% 115% at 38% 22%, ${bgShade(
                  bg,
                  0.08,
                )} 0%, ${bD} 48%, ${bDD} 100%)`,
              }}
            />
            <div
              style={{
                ...fill,
                background: `radial-gradient(70% 50% at 62% 30%, ${bgShadeA(
                  accent,
                  0.2,
                  0.3,
                )} 0%, transparent 55%)`,
              }}
            />
            <svg
              viewBox="0 0 100 100"
              preserveAspectRatio="xMidYMid slice"
              style={fill}
              xmlns="http://www.w3.org/2000/svg"
              aria-hidden="true"
            >
              {COSMOS_DOTS.map(([x, y, r, o, tier], i) => (
                <circle
                  key={i}
                  cx={x}
                  cy={y}
                  r={r}
                  fill={tier === 1 ? bgShadeA(accent, 0.5, 1) : "#fff"}
                  opacity={o}
                />
              ))}
            </svg>
            <div style={vig(0.3)} />
          </div>
        );

      // Starlight: true 4-point sparkle stars at varied sizes (plus faint dust)
      // over a night sky — distinct, twinkling, pristine.
      // Chrome: rich conic sweep with an added sheen highlight band.
      case "metallic":
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `conic-gradient(from 210deg at 50% 45%, ${bLL} 0deg, ${accent} 60deg, ${bD} 130deg, ${bDD} 180deg, ${bL} 250deg, ${aL} 310deg, ${bLL} 360deg)`,
              }}
            />
            <div
              style={{
                ...fill,
                background: `linear-gradient(100deg, transparent 30%, ${bgShadeA(
                  bg,
                  0.6,
                  0.45,
                )} 50%, transparent 62%)`,
                mixBlendMode: "screen",
              }}
            />
            <div style={vig(0.22)} />
          </div>
        );

      default:
        return (
          <div style={fill}>
            <div
              style={{
                ...fill,
                background: `linear-gradient(160deg, ${bL} 0%, ${bg} 70%, ${bD} 100%)`,
              }}
            />
            <div style={vig(0.18)} />
          </div>
        );
    }
  })();

  // Overlay the universal light bloom on top of whatever design rendered, so the
  // Light Position + Brightness controls affect every background consistently.
  return (
    <div style={fill}>
      {content}
      {lightBloom}
    </div>
  );
}
